/* ----------------------------------------------------------
   2. PHOTOS DE PROFIL
   ---------------------------------------------------------- */
function sourceAvatar(a) {
  return IMAGES[a.image];
}

/* ----------------------------------------------------------
   3. OUTILS
   ---------------------------------------------------------- */
var ETAPES = ["message", "imposteur", "recherche", "bilan"];
var ECRANS = ["intro"].concat(ETAPES);
var NB_INDICES = Object.keys(INDICES).length;

function $(s, parent) { return (parent || document).querySelector(s); }
function $$(s, parent) { return Array.prototype.slice.call((parent || document).querySelectorAll(s)); }

// Crée un élément HTML : el("p", { className: "x" }, ["texte", autreElement])
function el(balise, proprietes, enfants) {
  var e = document.createElement(balise);
  Object.keys(proprietes || {}).forEach(function (cle) {
    if (cle === "attrs") Object.keys(proprietes.attrs).forEach(function (a) { e.setAttribute(a, proprietes.attrs[a]); });
    else e[cle] = proprietes[cle];
  });
  (enfants || []).forEach(function (enfant) {
    e.appendChild(typeof enfant === "string" ? document.createTextNode(enfant) : enfant);
  });
  return e;
}

function message(conteneur, type, icone, texte) {
  conteneur.innerHTML = "";
  conteneur.appendChild(el("div", { className: "note note-" + type }, [
    el("span", { className: "note-icone", attrs: { "aria-hidden": "true" } }, [icone]),
    el("p", {}, [texte])
  ]));
}

function normaliser(t) {
  return t.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();
}

function profil(id) {
  for (var i = 0; i < PROFILS.length; i++) if (PROFILS[i].id === id) return PROFILS[i];
  return null;
}

/* ----------------------------------------------------------
   4. TEXTES ET IMAGES qui dépendent de la configuration
   ---------------------------------------------------------- */
function remplirTextes() {
  $$("[data-image]").forEach(function (img) { img.src = IMAGES[img.getAttribute("data-image")]; });
  $$(".nom-faux").forEach(function (e) { e.textContent = CONFIG.faux.nom; });
  $$(".pseudo-faux").forEach(function (e) { e.textContent = CONFIG.faux.pseudo; });
  $$(".pseudo-vrai").forEach(function (e) { e.textContent = profil(CONFIG.idVrai).pseudo; });

  var bulles = $("#bulles");
  bulles.innerHTML = "";
  CONFIG.debutPrenom.toUpperCase().split("").forEach(function (lettre) {
    bulles.appendChild(el("span", { className: "bulle" }, [lettre]));
  });
  for (var i = 0; i < CONFIG.lettresManquantes; i++) bulles.appendChild(el("span", { className: "bulle vide" }, ["?"]));
  $("#prenom-lu").textContent = "Le début du prénom est : " + CONFIG.debutPrenom.toUpperCase().split("").join(", ") +
    ". Il reste " + CONFIG.lettresManquantes + " lettres à trouver dans un autre fragment de rêve.";

  // Barre du détecteur : un segment par indice
  var barre = $("#detecteur-barre");
  barre.innerHTML = "";
  for (var j = 0; j < NB_INDICES; j++) barre.appendChild(el("span", {}, []));
}

/* ----------------------------------------------------------
   5. SAUVEGARDE de la progression (même onglet)
   ---------------------------------------------------------- */
var CLE = "imposteur-progression-v3";
var etat = { ecran: "intro", indices: [], pistes: [], motifOuvert: false, signale: false, ecartes: [], trouve: false, requete: CONFIG.rechercheDeDepart };

function sauver() { try { sessionStorage.setItem(CLE, JSON.stringify(etat)); } catch (e) { /* indisponible */ } }
function charger() { try { var b = sessionStorage.getItem(CLE); return b ? JSON.parse(b) : null; } catch (e) { return null; } }
function effacer() { try { sessionStorage.removeItem(CLE); } catch (e) { /* rien */ } }

/* ----------------------------------------------------------
   6. NAVIGATION + circuit de progression
   ---------------------------------------------------------- */
function majCircuit(ecran) {
  var actuel = ETAPES.indexOf(ecran);
  $$("#circuit li").forEach(function (li, i) {
    var statut = "";
    if (actuel > -1 && i < actuel) statut = "fait";
    if (i === actuel) statut = "en-cours";
    li.className = statut;
    if (statut === "en-cours") li.setAttribute("aria-current", "step");
    else li.removeAttribute("aria-current");
    $(".tuile-etat", li).textContent = statut === "fait" ? "terminé" : statut === "en-cours" ? "en cours" : "à venir";
  });
}

function afficher(ecran, options) {
  options = options || {};
  ECRANS.forEach(function (id) { document.getElementById(id).hidden = (id !== ecran); });
  majCircuit(ecran);
  etat.ecran = ecran;
  sauver();
  if (ecran === "recherche") montrerResultats(false);
  if (options.sansFocus) return;
  window.scrollTo(0, 0);
  var titre = $("#" + ecran + " h2");
  if (titre) titre.focus();
}

/* ----------------------------------------------------------
   7. ÉTAPE 1 : le message piège
   ---------------------------------------------------------- */
function initMessage() {
  var retour = $("#message-retour");
  $$("#message .choix").forEach(function (bouton) {
    bouton.addEventListener("click", function () {
      var choix = bouton.getAttribute("data-choix");
      if (choix === "envoyer") {
        bouton.classList.add("faux");
        message(retour, "erreur", "✗", "Stop ! Ce code sert à se connecter à VOTRE compte. En le donnant, vous donnez l'accès à vos données. On ne transmet jamais un code reçu par SMS, à personne.");
      } else if (choix === "demander") {
        message(retour, "info", "i", "Il répond : « Bah c'est moi ! Dépêche-toi stp. » Il esquive la question… Allez plutôt voir son profil.");
      } else {
        afficher("imposteur");
      }
    });
  });
}

/* ----------------------------------------------------------
   8. ÉTAPE 2 : la chasse aux indices
   ---------------------------------------------------------- */
function majImposteur(dernier) {
  // Éléments cliquables : indices trouvés et fausses pistes écartées
  $$("[data-indice]").forEach(function (b) {
    var trouve = etat.indices.indexOf(b.getAttribute("data-indice")) > -1;
    b.classList.toggle("trouve", trouve);
    b.setAttribute("aria-pressed", trouve ? "true" : "false");
  });
  $$("[data-piste]").forEach(function (b) {
    b.removeAttribute("aria-pressed");
    b.classList.toggle("ecarte-piste", etat.pistes.indexOf(b.getAttribute("data-piste")) > -1);
  });

  // Détecteur
  var n = etat.indices.length;
  $$("#detecteur-barre span").forEach(function (s, i) { s.classList.toggle("plein", i < n); });
  $("#detecteur-texte").textContent = n + (n > 1 ? " indices" : " indice") + " sur " + NB_INDICES;
  $("#detecteur").classList.toggle("complet", n === NB_INDICES);

  // Carnet
  var liste = $("#carnet-liste");
  liste.innerHTML = "";
  etat.indices.forEach(function (cle) { liste.appendChild(el("li", {}, [INDICES[cle].court])); });
  if (n === 0) liste.appendChild(el("li", { className: "carnet-vide" }, ["Aucun indice pour l'instant."]));

  var complet = n === NB_INDICES;
  $("#signaler").hidden = !complet || etat.motifOuvert || etat.signale;

  if (dernier) {
    var retour = $("#imposteur-retour");
    if (dernier.type === "piste") message(retour, "info", "i", PISTES[dernier.cle]);
    else if (complet) message(retour, "erreur", "!", INDICES[dernier.cle].explication + " Détecteur au maximum : ce compte est un faux. Signalez-le !");
    else message(retour, "erreur", "!", INDICES[dernier.cle].explication + " Encore " + (NB_INDICES - n) + " à trouver.");
  }
}

function ouvrirMotif(avecFocus) {
  etat.motifOuvert = true;
  sauver();
  $("#signaler").hidden = true;
  $("#imposteur-retour").innerHTML = "";
  var motif = $("#motif");
  motif.hidden = false;
  if (avecFocus) $("h3", motif).focus();
}

function signaler(avecFocus) {
  etat.signale = true;
  sauver();
  $("#motif").hidden = true;
  $$("[data-indice], [data-piste]").forEach(function (b) { b.disabled = true; });
  var ok = $("#signale-ok");
  ok.hidden = false;
  if (avecFocus) $("h3", ok).focus();
}

function initImposteur() {
  $$("[data-indice]").forEach(function (b) {
    b.addEventListener("click", function () {
      var cle = b.getAttribute("data-indice");
      if (etat.indices.indexOf(cle) > -1) return;
      etat.indices.push(cle);
      sauver();
      majImposteur({ type: "indice", cle: cle });
    });
  });
  $$("[data-piste]").forEach(function (b) {
    b.addEventListener("click", function () {
      var cle = b.getAttribute("data-piste");
      if (etat.pistes.indexOf(cle) === -1) etat.pistes.push(cle);
      sauver();
      majImposteur({ type: "piste", cle: cle });
    });
  });
  $("#signaler").addEventListener("click", function () { ouvrirMotif(true); });

  var retourMotif = $("#motif-retour");
  $$("#motif .choix").forEach(function (b) {
    b.addEventListener("click", function () {
      var motif = b.getAttribute("data-motif");
      if (motif === "usurpation") { signaler(true); return; }
      b.classList.add("faux");
      if (motif === "concours") message(retourMotif, "info", "i", "C'est louche, mais ce n'est pas le cœur du problème, qui est vraiment derrière ce compte ?");
      else message(retourMotif, "erreur", "✗", "Ne pas aimer sa musique n'est pas une raison de signaler un compte !");
    });
  });
  majImposteur(null);
}

/* ----------------------------------------------------------
   9. ÉTAPE 3 : retrouver le vrai compte
   ---------------------------------------------------------- */
var profilOuvert = null;

function correspond(p, requete) {
  if (!requete) return true;
  return normaliser(p.pseudo + " " + p.nom + " " + p.bio).indexOf(requete) > -1;
}

function dessinerResultats() {
  var requete = normaliser(etat.requete || "");
  var liste = $("#resultats");
  liste.innerHTML = "";
  var trouves = PROFILS.filter(function (p) { return correspond(p, requete); });

  trouves.forEach(function (p) {
    var badges = [];
    if (p.id === CONFIG.idFaux && etat.signale) badges.push(el("span", { className: "badge badge-signale" }, ["Signalé"]));
    var ecarte = etat.ecartes.indexOf(p.id) > -1;
    if (ecarte) badges.push(el("span", { className: "badge badge-ecarte" }, ["Écarté"]));

    var bouton = el("button", { type: "button", className: "compte-ligne" + (ecarte ? " ecarte" : "") }, [
      el("img", { className: "reseau-avatar", src: sourceAvatar(p.avatar), alt: "" }),
      el("span", { className: "compte-textes" }, [
        el("span", { className: "compte-pseudo" }, ["@" + p.pseudo].concat(badges)),
        el("span", {}, [p.nom]),
        el("span", { className: "compte-bio" }, [p.bio])
      ]),
      el("span", { className: "compte-voir", attrs: { "aria-hidden": "true" } }, ["Voir ›"])
    ]);
    bouton.setAttribute("data-id", p.id);
    bouton.setAttribute("aria-label", "Voir le profil @" + p.pseudo + ", " + p.nom +
      (p.id === CONFIG.idFaux && etat.signale ? ", signalé" : "") + (ecarte ? ", écarté" : ""));
    bouton.addEventListener("click", function () { ouvrirProfil(p.id); });
    liste.appendChild(el("li", {}, [bouton]));
  });

  if (trouves.length === 0) liste.appendChild(el("li", { className: "resultats-vide" }, ["Aucun compte trouvé. Essayez un autre mot."]));
  $("#compte-resultats").textContent = trouves.length + (trouves.length > 1 ? " comptes trouvés" : " compte trouvé");
}

function ouvrirProfil(id) {
  var p = profil(id);
  profilOuvert = id;
  var zone = $("#profil-ouvert");
  zone.innerHTML = "";

  var banniere = el("div", { className: "banniere", attrs: { "aria-hidden": "true" } }, []);
  if (p.banniere) banniere.style.background = "linear-gradient(135deg, #0e2554, " + p.banniere + ")";
  zone.appendChild(banniere);

  var badges = [];
  if (p.id === CONFIG.idFaux && etat.signale) badges.push(el("span", { className: "badge badge-signale" }, ["Signalé"]));
  zone.appendChild(el("div", { className: "profil-haut" }, [
    el("img", { className: "reseau-avatar grand-avatar", src: sourceAvatar(p.avatar), alt: p.avatar.alt }),
    el("div", { className: "profil-identite" }, [
      el("p", { className: "reseau-pseudo", id: "profil-ouvert-titre" }, ["@" + p.pseudo].concat(badges)),
      el("p", {}, [p.nom])
    ])
  ]));
  zone.appendChild(el("p", { className: "profil-infos" }, [p.depuis]));
  zone.appendChild(el("p", { className: "profil-stats" }, [
    el("span", {}, [el("strong", {}, [p.stats[0]]), " publications"]),
    el("span", {}, [el("strong", {}, [p.stats[1]]), " abonnés"]),
    el("span", {}, [el("strong", {}, [p.stats[2]]), " abonnements"])
  ]));
  zone.appendChild(el("p", { className: "reseau-bio" }, [p.bio]));
  zone.appendChild(el("p", { className: "onglet-publications" }, ["Publications"]));

  p.publications.forEach(function (pub) {
    var enfants = [];
    if (pub.image) enfants.push(el("img", { className: "publication-photo", src: IMAGES[pub.image], alt: pub.alt }));
    enfants.push(el("p", { className: "publication-texte" }, [el("strong", {}, [p.pseudo]), pub.texte]));
    enfants.push(el("p", { className: "publication-date" }, [pub.date]));
    zone.appendChild(el("div", { className: "publication" }, enfants));
  });

  $("#recherche-retour").innerHTML = "";
  $("#c-est-lui").disabled = etat.ecartes.indexOf(id) > -1;
  $("#vue-resultats").hidden = true;
  $("#vue-profil").hidden = false;
  window.scrollTo(0, 0);
  $("#retour-resultats").focus();
}

function montrerResultats(avecFocus) {
  $("#champ-recherche").value = etat.requete || "";
  dessinerResultats();
  $("#vue-profil").hidden = true;
  $("#vue-resultats").hidden = etat.trouve;
  if (avecFocus && profilOuvert) {
    var bouton = $('#resultats .compte-ligne[data-id="' + profilOuvert + '"]');
    if (bouton) bouton.focus();
  }
}

function trouver(avecFocus) {
  etat.trouve = true;
  sauver();
  $("#vue-profil").hidden = true;
  $("#vue-resultats").hidden = true;
  var ok = $("#trouve-ok");
  ok.hidden = false;
  if (avecFocus) { window.scrollTo(0, 0); $("h3", ok).focus(); }
}

function initRecherche() {
  var champ = $("#champ-recherche");
  champ.addEventListener("input", function () { etat.requete = champ.value; sauver(); dessinerResultats(); });
  $("#form-recherche").addEventListener("submit", function (e) { e.preventDefault(); });
  $("#retour-resultats").addEventListener("click", function () { montrerResultats(true); });
  $("#c-est-lui").addEventListener("click", function () {
    var p = profil(profilOuvert);
    if (p.id === CONFIG.idVrai) { trouver(true); return; }
    if (etat.ecartes.indexOf(p.id) === -1) etat.ecartes.push(p.id);
    sauver();
    $("#c-est-lui").disabled = true;
    message($("#recherche-retour"), "erreur", "✗", p.retour + " Retournez aux résultats pour chercher encore.");
  });
}

/* ----------------------------------------------------------
   10. DÉMARRAGE
   ---------------------------------------------------------- */
function demarrer() {
  remplirTextes();
  initMessage();
  initImposteur();
  initRecherche();

  document.addEventListener("click", function (e) {
    var cible = e.target.closest ? e.target.closest("[data-aller]") : null;
    if (cible) afficher(cible.getAttribute("data-aller"));
  });

  $("#recommencer").addEventListener("click", function () { effacer(); window.location.reload(); });

  var boutonTexte = $("#bouton-texte");
  boutonTexte.addEventListener("click", function () {
    var actif = document.documentElement.classList.toggle("grand-texte");
    boutonTexte.setAttribute("aria-pressed", actif ? "true" : "false");
  });

  // Reprise d'une enquête en cours
  var s = charger();
  if (s && ECRANS.indexOf(s.ecran) > -1) {
    etat.indices = (s.indices || []).filter(function (c) { return INDICES[c]; });
    etat.pistes = (s.pistes || []).filter(function (c) { return PISTES[c]; });
    etat.ecartes = s.ecartes || [];
    etat.requete = typeof s.requete === "string" ? s.requete : CONFIG.rechercheDeDepart;
    majImposteur(null);
    if (s.motifOuvert && !s.signale) ouvrirMotif(false);
    if (s.signale) { etat.motifOuvert = true; signaler(false); }
    if (s.trouve) trouver(false);
    afficher(s.ecran, { sansFocus: true });
  } else {
    afficher("intro", { sansFocus: true });
  }
}

